CREATE TABLE qhr_training_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,requester_id uuid,department_id uuid,training_type varchar(40) NOT NULL,reason text,estimated_cost numeric(20,2) NOT NULL DEFAULT 0,status varchar(40) NOT NULL DEFAULT 'pending',workflow_instance_id uuid,approved_by uuid,approval_note text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_training_requests_org_idx ON qhr_training_requests(org_id,status);
CREATE TABLE qhr_training_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,title varchar(200) NOT NULL,period varchar(40),request_ids jsonb NOT NULL DEFAULT '[]',budget numeric(20,2) NOT NULL DEFAULT 0,status varchar(40) NOT NULL DEFAULT 'draft',workflow_instance_id uuid,returned_count int NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_training_plans_org_idx ON qhr_training_plans(org_id,status);
CREATE TABLE qhr_training_courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,plan_id uuid REFERENCES qhr_training_plans(id),request_id uuid REFERENCES qhr_training_requests(id),title varchar(200) NOT NULL,delivery_type varchar(40) NOT NULL,trainer_info jsonb NOT NULL DEFAULT '{}',vendor_ref uuid,cost_amount numeric(20,2) NOT NULL DEFAULT 0,status varchar(40) NOT NULL DEFAULT 'planned',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
COMMENT ON COLUMN qhr_training_courses.vendor_ref IS 'Soft reference to future qpr_suppliers.id (Beat 12); nullable until procurement supplier master exists.';
CREATE INDEX qhr_training_courses_org_idx ON qhr_training_courses(org_id,delivery_type,status);
CREATE TABLE qhr_training_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,course_id uuid NOT NULL REFERENCES qhr_training_courses(id),session_no int NOT NULL,scheduled_at timestamptz,room text,status varchar(40) NOT NULL DEFAULT 'planned',cancel_reason text,rescheduled_from_session_id uuid REFERENCES qhr_training_sessions(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_training_sessions_org_idx ON qhr_training_sessions(org_id,course_id,status);
CREATE TABLE qhr_training_enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,course_id uuid NOT NULL REFERENCES qhr_training_courses(id),employee_id uuid NOT NULL,commitment_id uuid,status varchar(40) NOT NULL DEFAULT 'draft',attendance_pct numeric(6,2),final_test_score numeric(6,2),result varchar(40),certificate_no varchar(80),certificate_issued_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_training_enrollments_org_idx ON qhr_training_enrollments(org_id,course_id,status);
CREATE TABLE qhr_training_evaluations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,course_id uuid NOT NULL REFERENCES qhr_training_courses(id),enrollment_id uuid REFERENCES qhr_training_enrollments(id),evaluator_id uuid,organization_score int NOT NULL,teaching_score int NOT NULL,absorption_score int NOT NULL,comment text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_training_evaluations_org_idx ON qhr_training_evaluations(org_id,course_id);
CREATE TABLE qhr_training_commitments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,course_id uuid NOT NULL REFERENCES qhr_training_courses(id),employee_id uuid NOT NULL,min_service_months int NOT NULL DEFAULT 24,cost_amount numeric(20,2) NOT NULL DEFAULT 0,signed_at timestamptz NOT NULL DEFAULT now(),breach_refund_status varchar(40) NOT NULL DEFAULT 'none',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_training_commitments_org_idx ON qhr_training_commitments(org_id,course_id,employee_id);
CREATE TABLE qhr_training_vendor_proposals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,plan_id uuid NOT NULL REFERENCES qhr_training_plans(id),vendor_ref uuid,vendor_name varchar(200) NOT NULL,price numeric(20,2) NOT NULL,content text,duration text,format varchar(80),status varchar(40) NOT NULL DEFAULT 'draft',evaluation jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_training_vendor_proposals_org_idx ON qhr_training_vendor_proposals(org_id,plan_id,status);
CREATE TABLE qhr_training_monthly_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,period varchar(20) NOT NULL,course_count int NOT NULL DEFAULT 0,enrollment_count int NOT NULL DEFAULT 0,passed_count int NOT NULL DEFAULT 0,total_cost numeric(20,2) NOT NULL DEFAULT 0,scores_summary jsonb NOT NULL DEFAULT '{}',lessons_learned text,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX qhr_training_monthly_reports_org_period_idx ON qhr_training_monthly_reports(org_id,period);
